 CameraProposal? cachedProposal;MotionClip? proposalClip;Rig? proposalRig;
 CameraProposal Proposal(){if(CameraClip==null||Rig==null)throw new InvalidOperationException(UiText.T("t0099"));if(cachedProposal==null||proposalClip!=CameraClip||proposalRig!=Rig){cachedProposal=CameraAnalysis.Analyze(CameraClip,Rig);proposalClip=CameraClip;proposalRig=Rig;}return cachedProposal;}
