 async Task<MotionClip> LoadMotion(string path,int? bindingIndex=null,string? proof=null,Rig? targetRig=null){
  var rig=targetRig??Rig;
  while(true){MotionClip? candidate=null;try{candidate=await Task.Run(()=>MotionClip.Load(path,bindingIndex,proof));if(rig!=null)candidate.ValidateRig(rig);return candidate;}
   catch(HkxSelectionRequired choice){var window=new Window{Owner=this,Title=UiText.T("t0110"),Width=680,Height=260,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(new TextBlock{Text=UiText.T("t0111"),TextWrapping=TextWrapping.Wrap});var list=new ComboBox{Margin=new Thickness(0,14,0,14),ItemsSource=choice.Choices.Select(c=>UiText.F("t0112", c.BindingIndex, c.AnimationIndex, c.Type, c.Duration, c.Tracks)).ToArray(),SelectedIndex=-1};panel.Children.Add(list);var ok=new Button{Content=UiText.T("t0113"),IsEnabled=false};list.SelectionChanged+=(_,_)=>ok.IsEnabled=list.SelectedIndex>=0;ok.Click+=(_,_)=>window.DialogResult=true;panel.Children.Add(ok);window.Content=panel;if(window.ShowDialog()!=true)throw new OperationCanceledException(UiText.T("t0114"));bindingIndex=choice.Choices[list.SelectedIndex].BindingIndex;}
   catch(HkxMappingRequired mapping){if(rig==null)throw;var window=new Window{Owner=this,Title=UiText.T("t0115"),Width=680,Height=310,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(new TextBlock{Text=Path.GetFileName(path)+"\n\n"+mapping.Message+UiText.T("t0116")+rig.Name+UiText.T("t0117"),TextWrapping=TextWrapping.Wrap});var ok=new Button{Content=UiText.T("t0118"),Margin=new Thickness(0,14,0,0)};ok.Click+=(_,_)=>window.DialogResult=true;panel.Children.Add(ok);window.Content=panel;if(window.ShowDialog()!=true)throw new OperationCanceledException(UiText.T("t0119"));proof=candidate!.MappingProofFor(rig);}
  }
 }
 async Task DiagnoseHkx()=>await Guard(async()=>{
  var open=new OpenFileDialog{Filter=UiText.T("t0120"),Title=UiText.T("t0121")};if(open.ShowDialog(this)!=true)return;SetBusy(true,UiText.T("t0122"));var rig=Rig??await Task.Run(()=>DanceStudio.Rig.Load(DanceStudio.Rig.BuiltinId));var loaded=new[]{Dance,CameraClip}.FirstOrDefault(x=>x!=null&&Path.GetFullPath(x.Path).Equals(Path.GetFullPath(open.FileName),StringComparison.OrdinalIgnoreCase));var report=await Task.Run(()=>HkxDiagnostics.Inspect(open.FileName,rig,loaded?.BindingIndex,loaded?.IdentityRigProof));SetBusy(false,UiText.T("t0123"));
